import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';import {gzipSync,gunzipSync} from 'node:zlib';import {createHash} from 'node:crypto';
import {RemoteD1Database} from '../runner/report2-d1-adapter.mjs';import {loadDailyUsageAggregate,evaluateDailyReservationBudget,evaluateWithinRunReservation,reserveRunBudget,finalizeRunUsage} from '../runner/d1-preaction-budget-guard.mjs';
const root=path.resolve('runtime'),load=p=>import(pathToFileURL(path.join(root,p))),{collectWikimediaAttention,WIKIMEDIA_LIMITS}=await load('src/wikimedia-attention-context.mjs'),{consumeEvidenceV2}=await load('src/evidence-v2.mjs'),{consumeBlockResultContext}=await load('src/block-result-context.mjs'),{buildRuntimeCanonicalBundle}=await load('src/canonical-runtime-adapter.mjs'),{createUnifiedHttpBudget}=await load('src/unified-budget.mjs'),{auditCandidateBlocks,planCandidateEvidenceRoutes}=await load('src/candidate-evidence-v2-runtime.mjs');
const started=Date.now(),run_id='ACTUAL_WIKIMEDIA_NATIVE_PAGES:'+process.env.GITHUB_RUN_ID+':'+started,reservation={rows_read:1500,rows_written:100},db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),budget=createUnifiedHttpBudget(),raw=[],results=[],hash=b=>createHash('sha256').update(b).digest('hex'),proof={schema:'ACTUAL_WIKIMEDIA_NATIVE_PAGES_20261007_V1',status:'NOT_STARTED',run_id,head:process.env.GITHUB_SHA,cloud_run:Number(process.env.GITHUB_RUN_ID),source_http_cap:2,limits:WIKIMEDIA_LIMITS,MAIN:0,Telegram:0,new_fresh_SENT:false,source_clocks_refreshed:false,primary_attention_substituted:false,results};
let reserved=false,http=0;const within=()=>evaluateWithinRunReservation({reservation,currentUsage:db.usageSnapshot(),extraRowsRead:200,extraRowsWritten:30}).allowed;
try{
 const universe=JSON.parse(gunzipSync(fs.readFileSync('checkpoints/htx-all-modes-crypto-futures-universe-20261004.json.gz')));assert.equal(universe.assets.length,102);assert.equal(universe.contracts.length,119);
 proof.day_admission=evaluateDailyReservationBudget({daily:await loadDailyUsageAggregate(db,started),nextReservation:reservation,maxDailyReads:3500000,maxDailyWrites:70000});assert.equal(proof.day_admission.allowed,true);proof.d1_reservation=await reserveRunBudget(db,{reservationId:run_id,now:started,reservation});reserved=true;
 for(const [contract,chain,page]of [['ETH-USDT','ethereum','Ethereum'],['BTC-USDT','bitcoin','Bitcoin']]){
 assert.ok(universe.assets.some(a=>a.symbol===contract.replace('-USDT','')));assert.equal(within(),true,'D1_HEADROOM_REQUIRED');
 const asset_identity={chain,asset_kind:'NATIVE',native_asset_id:chain+':mainnet',contract_or_mint:null},fetch_impl=async(url,opts)=>{assert.ok(http<2&&within());assert.equal(new URL(url).origin,'https://wikimedia.org');assert.ok(url.includes('/'+page+'/daily/'));http++;const response=await fetch(url,opts),chunks=[];let size=0;for await(const chunk of response.body){size+=chunk.length;assert.ok(size<=100000,'RESPONSE_BOUNDS');chunks.push(chunk);}const bytes=Buffer.concat(chunks);raw.push({url:String(url),http_status:response.status,received_ts:Date.now(),body_sha256:hash(bytes),raw_body_utf8:bytes.toString()});return new Response(bytes,{status:response.status,headers:response.headers});};
 const result=await collectWikimediaAttention({db,fetch_impl,request_admit:r=>budget.reserve(r),contract,run_id,asset_identity,now:Date.now(),clock:Date.now});
 results.push({contract,asset_identity,result});assert.equal(result.status,'CLOSED','ACTUAL_SOURCE_NOT_CLOSED:'+result.status);assert.equal(result.evidence.length,1);assert.ok(planCandidateEvidenceRoutes({contract,asset_identity,run_id,now:Date.now()}).routes.some(x=>x.name==='WIKIMEDIA'));
 const now=Date.now(),context=consumeBlockResultContext({evidence:result.evidence,contract,now});assert.equal(context.facts.length,1);assert.equal(consumeEvidenceV2(result.evidence,{base_interest:70,decision_ts:now}).adjustment,0);
 const input={contract,run_id,snapshot_id:run_id+':'+contract+':'+now,observed_ts:now},before=buildRuntimeCanonicalBundle(input),after=buildRuntimeCanonicalBundle({...input,internal_market_context:{internal_only:true,evidence_v2:{evidence:result.evidence,sources:{WIKIMEDIA_ATTENTION:result}}}});
 assert.ok(after.manual.ok);assert.ok(after.manual.text.includes('Внимание к статье '+page));assert.ok(after.block_rendered_results.used_context_block_ids.includes('N06'));assert.deepEqual(after.canonical.scores,before.canonical.scores);assert.equal(after.canonical.state,before.canonical.state);assert.equal(after.canonical.direction,before.canonical.direction);assert.deepEqual(after.canonical.targets,before.canonical.targets);
 const audit=auditCandidateBlocks({sources:{WIKIMEDIA_ATTENTION:result},evidence:result.evidence,decision_ts:now});assert.equal(audit.blocks.N06.checked,false);assert.ok(audit.blocks.N06.missing_required.includes('BLUESKY_PUBLIC'));
 Object.assign(results.at(-1),{context,report:{manual:after.manual,rendered_use:after.block_rendered_results},primary_requirement_unchanged:true,score_adjustment:0});
 }
 proof.status='ACTUAL_EXACT_NATIVE_PAGES_AND_ASSEMBLED_NEUTRAL_N06_CONSUMERS_CLOSED';
}catch(e){proof.status='ACTUAL_WIKIMEDIA_NATIVE_PAGES_NOT_CLOSED';proof.reason=String(e.message).slice(0,240);}
finally{
 proof.sourceHTTP=http;proof.D1=db.usageSnapshot();if(reserved){proof.finalized_usage=await finalizeRunUsage(db,{reservationId:run_id,sourceRunId:process.env.GITHUB_RUN_ID,now:Date.now(),usage:db.usageSnapshot()});proof.D1_actual=db.usageSnapshot();}
 assert.equal(proof.D1_actual?.unknown_ops??proof.D1.unknown_ops,0);fs.mkdirSync('audit-output',{recursive:true});const bytes=gzipSync(Buffer.from(JSON.stringify({proof,raw})),{mtime:0});proof.raw_gzip_sha256=hash(bytes);fs.writeFileSync('audit-output/wikimedia-native-pages-raw.json.gz',bytes);fs.writeFileSync('audit-output/wikimedia-native-pages-live-proof.json',JSON.stringify(proof,null,2)+'\n');console.log(JSON.stringify({status:proof.status,reason:proof.reason,sourceHTTP:http,D1:proof.D1_actual??proof.D1,MAIN:0,Telegram:0}));}
assert.equal(proof.status,'ACTUAL_EXACT_NATIVE_PAGES_AND_ASSEMBLED_NEUTRAL_N06_CONSUMERS_CLOSED');
